bodyHtml:
{% set store = cms.commerce.storeName() %}
{% set renewal = data.kind == 'renewal' %}
{% set when = data.paidAt|default(data.created) %}
<h1>{% if renewal %}Your renewal receipt{% else %}Thank you for your order{% endif %}</h1>
<p>{% if renewal %}{{ store|e }} has taken the payment for your renewal.{% else %}{{ store|e }} has received your payment.{% endif %} This is your receipt for order {{ data.number|e }}{% if when %}, dated {{ when|date('F j, Y')|e }}{% endif %}.</p>

<table cellpadding="6" cellspacing="0" width="100%">
{% for line in data.lines %}
	<tr>
		<td>{{ line.title|e }} &times; {{ line.qty|e }}</td>
		<td align="right">{{ line.lineTotal|money(data.currency) }}</td>
	</tr>
{% endfor %}
	<tr>
		<td>Subtotal</td>
		<td align="right">{{ data.subtotal|money(data.currency) }}</td>
	</tr>
{% if data.discountCode %}
	<tr>
		<td>Discount ({{ data.discountCode|e }})</td>
		<td align="right">{% if data.discountTotal %}-{{ data.discountTotal|money(data.currency) }}{% else %}Free shipping{% endif %}</td>
	</tr>
{% endif %}
{% if data.shippingTotal %}
	<tr>
		<td>Shipping</td>
		<td align="right">{{ data.shippingTotal|money(data.currency) }}</td>
	</tr>
{% endif %}
{% if data.taxTotal %}
	<tr>
		<td>Tax</td>
		<td align="right">{{ data.taxTotal|money(data.currency) }}</td>
	</tr>
{% endif %}
	<tr>
		<td><strong>Total</strong></td>
		<td align="right"><strong>{{ data.grandTotal|money(data.currency) }}</strong></td>
	</tr>
</table>

{% set downloads = cms.commerce.downloads(data) %}
{% if downloads %}
<h2>Your downloads</h2>
<ul>
{% for download in downloads %}
	<li>{% if download.url %}<a href="{{ download.url|e('html_attr') }}">{{ download.fileName|e }}</a>{% else %}{{ download.fileName|e }}{% endif %}</li>
{% endfor %}
</ul>
<p>These links work for {{ cms.config('commerce').downloadTtlHours|default(72)|e }} hours. After that, open your order below for new ones.</p>
{% endif %}

{% set orderUrl = cms.commerce.orderUrl(data) %}
{% if orderUrl %}
<p><a href="{{ orderUrl|e('html_attr') }}">View your order</a></p>
{% endif %}

{% if renewal and subscription is defined %}
<p><a href="{{ cms.commerce.subscriptionUrl(subscription)|e('html_attr') }}">Manage your subscription</a></p>
{% endif %}

<p>If you have a question about this order, reply to this email.</p>
<p>{{ store|e }}</p>

